def parse_csv_rows(text):
    reader = csv.DictReader(io.StringIO(text.strip()))
    return list(reader)

wc_rows = parse_csv_rows(wc_export_data)
final_rows = parse_csv_rows(final_desired_data)

print(f"Total WC rows: {len(wc_rows)}")
print(f"Total Final rows: {len(final_rows)}")

wc_by_sku = {}
wc_by_url = {}
for r in wc_rows:
    sku = r.get('SKU', '').strip()
    url = r.get('Meta: _Product_Link', '').strip()
    if sku:
        wc_by_sku[sku] = r
    if url:
        wc_by_url[url] = r

results = []
for f in final_rows:
    sku = f['SKU'].strip()
    trendyol_url = f.get('Meta: _trendyol', '').strip()
    match_by_sku = wc_by_sku.get(sku)
    match_by_url = wc_by_url.get(trendyol_url.split('?')[0]) or wc_by_url.get(trendyol_url)
    
    # If not found by full url, match by path
    if not match_by_url and trendyol_url:
        t_slug = trendyol_url.split('/')[-1].split('?')[0]
        for w_u, w_r in wc_by_url.items():
            if t_slug in w_u:
                match_by_url = w_r
                break
                
    results.append({
        'final_sku': sku,
        'final_name': f['Name'],
        'found_by_sku': bool(match_by_sku),
        'found_by_url': bool(match_by_url),
        'matched_wc_id': match_by_sku['ID'] if match_by_sku else (match_by_url['ID'] if match_by_url else None),
        'matched_wc_sku': match_by_sku['SKU'] if match_by_sku else (match_by_url['SKU'] if match_by_url else None),
        'matched_wc_type': match_by_sku['Type'] if match_by_sku else (match_by_url['Type'] if match_by_url else None),
        'matched_wc_published': match_by_sku['Published'] if match_by_sku else (match_by_url['Published'] if match_by_url else None),
        'matched_wc_has_images': bool(match_by_sku.get('Images') if match_by_sku else (match_by_url.get('Images') if match_by_url else False)),
        'price': f['Regular Price'],
        'homepage': f['Homepage'],
        'sizes': {sz: f[sz] for sz in ['xs', 's', 'm', 'l', 'xl']}
    })

print("\n" + "="*80)
print("PRODUCT INTEGRITY & COMPARISON SUMMARY (20 PRODUCTS)")
print("="*80)
for i, r in enumerate(results, 1):
    status = "OK" if r['found_by_sku'] else "SKU MISMATCH"
    print(f"{i:02d}. [{status}] Desired SKU: {r['final_sku']:<15} | WC ID: {str(r['matched_wc_id']):<5} | WC SKU: {str(r['matched_wc_sku']):<15} | Type: {str(r['matched_wc_type']):<8} | Pub: {str(r['matched_wc_published']):<2} | Img: {str(r['matched_wc_has_images']):<5} | HP: {r['homepage']:<18} | Price: {r['price']}")
    stock_str = " ".join([f"{k.upper()}:{v}" for k, v in r['sizes'].items()])
    print(f"    Name: {r['final_name']}")
    print(f"    Stock by Size -> {stock_str}")

